CREATE TABLE IF NOT EXISTS permissions (permission_id BIGINT AUTO_INCREMENT PRIMARY KEY, permission_key VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS role_permissions (role_id BIGINT NOT NULL, permission_id BIGINT NOT NULL, PRIMARY KEY(role_id, permission_id), CONSTRAINT fk_rp_permission FOREIGN KEY(permission_id) REFERENCES roles(role_id) ON DELETE CASCADE);
INSERT IGNORE INTO permissions(permission_key,description) VALUES ('ASSET_READ','View assets'),('ASSET_WRITE','Manage assets'),('ASSET_LIFECYCLE','Dispose and repair assets'),('REPORT_EXPORT','Export reports'),('USER_ADMIN','Manage users');
CREATE TABLE IF NOT EXISTS asset_disposals (disposal_id BIGINT AUTO_INCREMENT PRIMARY KEY, company_id BIGINT NOT NULL, asset_id BIGINT NOT NULL, requested_by BIGINT, disposal_type VARCHAR(40) NOT NULL, reason VARCHAR(500), disposal_date DATE, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', approved_by BIGINT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_disposal_company(company_id), CONSTRAINT fk_disposal_asset FOREIGN KEY(asset_id) REFERENCES assets(asset_id));
CREATE TABLE IF NOT EXISTS repair_history (repair_id BIGINT AUTO_INCREMENT PRIMARY KEY, company_id BIGINT NOT NULL, asset_id BIGINT NOT NULL, technician_id BIGINT, issue_description VARCHAR(500) NOT NULL, repair_action VARCHAR(1000), cost DECIMAL(14,2), started_at DATE, completed_at DATE, status VARCHAR(30) NOT NULL DEFAULT 'OPEN', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_repair_company(company_id), CONSTRAINT fk_repair_asset FOREIGN KEY(asset_id) REFERENCES assets(asset_id));
